<?php declare(strict_types=1);
use App\Core\Database\Database;
use App\Modules\SubcontractBoq\DTOs\BoqItemData;
use App\Modules\Subcontracts\DTOs\SubcontractData;
use App\Modules\Subcontracts\Services\SubcontractService;
/** @var Database $db */$db=$app->make(Database::class);/** @var SubcontractService $service */$service=$app->make(SubcontractService::class);$suffix=bin2hex(random_bytes(4));$ids=[];
try{$ws=$db->execute('SELECT id FROM work_sections WHERE is_active=1 ORDER BY id LIMIT 1')->fetch_assoc();$unit=$db->execute("SELECT id FROM units WHERE code='pcs' AND is_active=1 LIMIT 1")->fetch_assoc();if(!$ws||!$unit)throw new RuntimeException('Wizard references missing.');$db->execute("INSERT INTO clients(client_code,client_type,name)VALUES(?,'individual','Wizard Client')",['WCL-'.$suffix]);$client=(int)$db->connection()->insert_id;$db->execute("INSERT INTO projects(project_code,name,client_id,project_type,status)VALUES(?,'Wizard Project',?,'contracting','active')",['WPR-'.$suffix,$client]);$project=(int)$db->connection()->insert_id;$db->execute("INSERT INTO vendors(vendor_code,vendor_type,name)VALUES(?,'subcontractor','Wizard Vendor')",['WVN-'.$suffix]);$vendor=(int)$db->connection()->insert_id;$db->execute('INSERT INTO vendor_work_sections(vendor_id,work_section_id)VALUES(?,?)',[$vendor,(int)$ws['id']]);$id=$service->save(new SubcontractData($project,(int)$ws['id'],$vendor,'boq','Wizard Contract',null,'2026-10-11','2026-10-11',null,null),null,[new BoqItemData(1,'Wizard Item','quantity',(int)$unit['id'],'2.0000','15.00',null,null)]);$row=$db->execute('SELECT s.subcontract_code,i.line_total FROM subcontracts s JOIN subcontract_boqs b ON b.subcontract_id=s.id JOIN subcontract_boq_sections bs ON bs.subcontract_boq_id=b.id JOIN subcontract_boq_items i ON i.subcontract_boq_section_id=bs.id WHERE s.id=?',[$id])->fetch_assoc();if(!$row||!preg_match('/^SUB-2026-\d{4,}$/',$row['subcontract_code'])||$row['line_total']!=='30.00')throw new RuntimeException('Wizard did not atomically create the contract scope and item.');}
finally{if(isset($id)){$db->execute('DELETE i FROM subcontract_boq_items i JOIN subcontract_boq_sections bs ON bs.id=i.subcontract_boq_section_id JOIN subcontract_boqs b ON b.id=bs.subcontract_boq_id WHERE b.subcontract_id=?',[$id]);$db->execute('DELETE bs FROM subcontract_boq_sections bs JOIN subcontract_boqs b ON b.id=bs.subcontract_boq_id WHERE b.subcontract_id=?',[$id]);$db->execute('DELETE FROM subcontract_boqs WHERE subcontract_id=?',[$id]);$db->execute('DELETE FROM subcontracts WHERE id=?',[$id]);}if(isset($vendor)){$db->execute('DELETE FROM vendor_work_sections WHERE vendor_id=?',[$vendor]);$db->execute('DELETE FROM vendors WHERE id=?',[$vendor]);}if(isset($project))$db->execute('DELETE FROM projects WHERE id=?',[$project]);if(isset($client))$db->execute('DELETE FROM clients WHERE id=?',[$client]);}
